\begin{tikzpicture}
\begin{axis}[
    width=0.78\textwidth,
    height=0.50\textwidth,
    xmin=-3, xmax=3,
    ymin=-4, ymax=6,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={},
    xtick={-3,-2,-1,0,1,2,3},
    ytick={-4,-2,0,2,4,6},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    legend style={draw=none, fill=none, at={(0.5,-0.20)}, anchor=north, legend columns=2, font=\small}
]
\addplot[thick, domain=-3:3, samples=200] {cosh(x)};
\addlegendentry{\(\cosh x\)}
\addplot[thick, dashed, domain=-3:3, samples=200] {sinh(x)};
\addlegendentry{\(\sinh x\)}
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.72\textwidth,
    height=0.52\textwidth,
    xmin=-3, xmax=3,
    ymin=-2.5, ymax=2.5,
    axis lines=middle,
    xlabel={\(X\)},
    ylabel={\(Y\)},
    xtick={-2,-1,0,1,2},
    ytick={-2,-1,0,1,2},
    grid=both,
    grid style={line width=.1pt, draw=gray!25}
]
% right branch: X = cosh t, Y = sinh t
\addplot[thick, domain=-1.8:1.8, samples=200] ({cosh(x)},{sinh(x)});
% left branch
\addplot[thick, domain=-1.8:1.8, samples=200] ({-cosh(x)},{sinh(x)});
\addplot[only marks, mark=*] coordinates {(1.543,1.175)};
\node[anchor=west] at (axis cs:1.6,1.2) {\((\cosh t,\sinh t)\)};
\node[anchor=west] at (axis cs:1.1,-2.0) {\(X^2-Y^2=1\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[width=0.30\textwidth,height=0.29\textwidth,xmin=-3,xmax=3,ymin=-2.4,ymax=2.4,axis lines=middle,xlabel={$x$},title={$\operatorname{arsinh}x$},xtick={-2,0,2},ytick={-2,0,2}]
\addplot[thick,domain=-3:3,samples=100]{ln(x+sqrt(x*x+1))};
\end{axis}
\begin{axis}[at={(0.34\textwidth,0)},anchor=south west,width=0.30\textwidth,height=0.29\textwidth,xmin=0,xmax=4,ymin=-0.2,ymax=2.4,axis lines=middle,xlabel={$x$},title={$\operatorname{arcosh}x$},xtick={1,2,3,4},ytick={0,1,2}]
\addplot[thick,domain=1:4,samples=150]{ln(x+sqrt(x*x-1))};
\addplot[only marks,mark=*] coordinates {(1,0)};
\end{axis}
\begin{axis}[at={(0.68\textwidth,0)},anchor=south west,width=0.30\textwidth,height=0.29\textwidth,xmin=-1.25,xmax=1.25,ymin=-2.4,ymax=2.4,axis lines=middle,xlabel={$x$},title={$\operatorname{artanh}x$},xtick={-1,0,1},ytick={-2,0,2}]
\addplot[thick,domain=-0.98:0.98,samples=150]{0.5*ln((1+x)/(1-x))};
\draw[dashed] (axis cs:-1,-2.4)--(axis cs:-1,2.4);
\draw[dashed] (axis cs:1,-2.4)--(axis cs:1,2.4);
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.78\textwidth,
    height=0.48\textwidth,
    xmin=-3, xmax=3,
    ymin=0, ymax=5.2,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-3,-2,-1,0,1,2,3},
    ytick={0,1,2,3,4,5},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    legend style={draw=none, fill=none, at={(0.5,-0.20)}, anchor=north, legend columns=2, font=\small}
]
\addplot[thick, domain=-2.7:2.7, samples=200] {cosh(x)};
\addlegendentry{\(y=\cosh x\)}
\addplot[thick, dashed, domain=-2.7:2.7, samples=200] {1+x^2/2};
\addlegendentry{\(y=1+\frac{x^2}{2}\)}
\addplot[only marks, mark=*, samples at={-2.2, 2.2}] {cosh(x)};
\node[anchor=north] at (axis cs:0.7,0.88) {lowest point};
\end{axis}
\end{tikzpicture}
